testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { interpretarLinhaDeRequest } from './solution.mjs';

test('linha simples: GET /sobre', () => {
  assert.deepEqual(interpretarLinhaDeRequest('GET /sobre HTTP/1.1'), { method: 'GET', path: '/sobre' });
});

test('limite: query string fica de fora do caminho', () => {
  assert.deepEqual(interpretarLinhaDeRequest('GET /busca?q=node HTTP/1.1'), { method: 'GET', path: '/busca' });
});

test('limite: POST com caminho raiz', () => {
  assert.deepEqual(interpretarLinhaDeRequest('POST / HTTP/1.1'), { method: 'POST', path: '/' });
});

test('linha vazia: lança erro', () => {
  assert.throws(() => interpretarLinhaDeRequest('   '), /inválida/);
});

solutionCode:
export function interpretarLinhaDeRequest(linha) {
  if (typeof linha !== 'string' || linha.trim() === '') {
    throw new Error('linha de request inválida');
  }

  const partes = linha.trim().split(' ');
  if (partes.length < 2) {
    throw new Error('linha de request inválida');
  }

  const metodo = partes[0];
  const caminho = partes[1].split('?')[0];
  return { method: metodo, path: caminho };
}
